#[inline(always)]
#[must_use]
fn lerp_impl(self, end: Self, s: f32) -> Self {
    (self * (1.0 - s) + end * s).normalize()
}

/// Performs a linear interpolation between `self` and `rhs` based on
/// the value `s`.
///
/// When `s` is `0.0`, the result will be equal to `self`.  When `s`
/// is `1.0`, the result will be equal to `rhs`.
///
/// # Panics
///
/// Will panic if `self` or `end` are not normalized when `glam_assert` is enabled.
#[doc(alias = "mix")]
#[inline]
#[must_use]
pub fn lerp(self, end: Self, s: f32) -> Self {
    glam_assert!(self.is_normalized());
    glam_assert!(end.is_normalized());

    const NEG_ZERO: float32x4_t = f32x4_from_array([-0.0; 4]);
    unsafe {
        let dot = dot4_into_f32x4(self.0, end.0);
        // Calculate the bias, if the dot product is positive or zero, there is no bias
        // but if it is negative, we want to flip the 'end' rotation XYZW components
        let bias = vandq_u32(vreinterpretq_u32_f32(dot), vreinterpretq_u32_f32(NEG_ZERO));
        self.lerp_impl(
            Self(vreinterpretq_f32_u32(veorq_u32(
                vreinterpretq_u32_f32(end.0),
                bias,
            ))),
            s,
        )
    }
}

#[inline]
pub(crate) unsafe fn dot4(lhs: float32x4_t, rhs: float32x4_t) -> f32 {
    let x2_y2_z2_w2 = vmulq_f32(lhs, rhs);
    // TODO: horizontal add - might perform bad?
    vaddvq_f32(x2_y2_z2_w2)
}

#[inline]
pub(crate) unsafe fn dot4_into_f32x4(lhs: float32x4_t, rhs: float32x4_t) -> float32x4_t {
    let dot = dot4(lhs, rhs);
    vld1q_dup_f32(&dot as *const f32)
}

pub fn linear_blend_mut(&mut self, other: &BonePose, alpha: f32) {
    self.rotation = either_or_mix(self.rotation, other.rotation, |a, b| a.slerp(b, alpha));
    self.translation =
        either_or_mix(self.translation, other.translation, |a, b| a.lerp(b, alpha));
    self.scale = either_or_mix(self.scale, other.scale, |a, b| a.lerp(b, alpha));
    self.weights = either_or_mix(self.weights.clone(), other.weights.clone(), |a, b| {
        let length = a.len().max(b.len());
        (0..length)
            .map(|index| {
                let old = a.get(index).copied().unwrap_or(0.0);
                let new = b.get(index).copied().unwrap_or(0.0);
                old + (new - old) * alpha
            })
            .collect()
    });

pub fn linear_add(&self, other: &BonePose) -> Self {
    Self {
        rotation: either_or_mix(self.rotation, other.rotation, |a, b| {
            linear_add_quaternion(a, b)
        }),
        translation: either_or_mix(self.translation, other.translation, |a, b| a + b),
        scale: either_or_mix(self.scale, other.scale, |a, b| a + b),
        weights: either_or_mix(self.weights.clone(), other.weights.clone(), |a, b| {
            a.into_iter().zip(b).map(|(a, b)| a + b).collect()
        }),
    }
}

pub fn scalar_mult(&self, alpha: f32) -> Self {
    Self {
        rotation: self.rotation.map(|r| r * alpha),
        translation: self.translation.map(|t| alpha * t),
        scale: self.scale.map(|s| alpha * s),
        weights: self
            .weights
            .clone()
            .map(|w| w.into_iter().map(|a| alpha * a).collect()),
    }
}

pub fn normalize_quat(&self) -> Self {
    Self {
        rotation: self.rotation.map(|r| r.normalize()),
        translation: self.translation,
        scale: self.scale,

        (None, None) => None,
        (Some(a), None) => Some(a),
        (None, Some(b)) => Some(b),
    }
}

fn linear_add_quaternion(a: Quat, b: Quat) -> Quat {
    if a.dot(b) < 0. { a - b } else { a + b }
}

pub(crate) fn apply_mesh_space_layered_blend_with_hierarchy(
    base: &mut Pose,
    overlay: &Pose,
    alpha: f32,
    bone_mask: &BoneMask,
    skeleton: &Skeleton,
    hierarchy: &[(BoneId, Option<usize>)],
) {
    let alpha = alpha.clamp(0.0, 1.0);
    if alpha <= WEIGHT_THRESHOLD {
        return;
    }

    let source_mesh = mesh_rotations(base, skeleton, hierarchy);
    let overlay_mesh = mesh_rotations(overlay, skeleton, hierarchy);
    LinearInterpolator {
        bone_mask: bone_mask.clone(),
    }
    .interpolate_pose(base, overlay, alpha);

    let mut output_mesh = Vec::with_capacity(hierarchy.len());

    for (index, &(bone, parent)) in hierarchy.iter().enumerate() {
        let mask_weight = bone_mask.bone_weight(&bone).clamp(0.0, 1.0);
        let weight = (alpha * mask_weight).clamp(0.0, 1.0);
        let rotation = if weight <= WEIGHT_THRESHOLD {
            source_mesh[index]
        } else {
            let source_rotation = source_mesh[index];
            let overlay_rotation = overlay_mesh[index];
            source_rotation.lerp(overlay_rotation, weight).normalize()
        };
        output_mesh.push(rotation);

        if weight <= WEIGHT_THRESHOLD
            && !base.paths.contains_key(&bone)
            && !overlay.paths.contains_key(&bone)
            && parent.is_none_or(|parent| {
                output_mesh.get(parent) == source_mesh.get(parent)
            })
        {
            continue;
        }
        let local = parent
            .and_then(|parent| output_mesh.get(parent).copied())
            .map(|parent| parent.inverse() * rotation)
            .unwrap_or(rotation)
            .normalize();
        if let Some(index) = base.paths.get(&bone).copied() {
            base.bones[index].rotation = Some(local);
        } else {
            base.add_bone(
                BonePose {
                    rotation: Some(local),
                    ..default()
                },
                bone,
            );
        }
    }

let root_motion = source_layered_root_motion(&base, &overlays, &weights, root_source, root_weight,
    self.blend_root_motion_based_on_root_bone);
let mut mask = data.mask.clone();
let sources = &data.sources;
let mut target = data.reference.clone();
for (bone, index) in &target.paths {
    let reference = target.bones[*index].clone();
    if let Some(base_index) = base.paths.get(bone).copied() {
        base.bones[base_index] = reference.overlay(&base.bones[base_index]);
    } else { base.add_bone(reference.clone(), *bone); }
    let mut source = sources.get(bone).copied().unwrap_or(0);
    let weight = (mask.bone_weight(bone) * weights[source]).clamp(0.0, 1.0);
    let weight = if weight <= 1e-5 { source = 0; 0.0 } else if weight >= 1.0 - 1e-5 { 1.0 } else { weight };
    mask.update_bone_weight(*bone, weight);
    if let Some(overlay) = overlays[source].as_ref().and_then(|pose| pose.get_bone(*bone)) {
        target.bones[*index] = reference.overlay(overlay);
    }
}
if self.mesh_space_rotation_blend {
    crate::extensions::mesh_space_layered_blend::apply_mesh_space_layered_blend_with_hierarchy(&mut base, &target, 1.0, &mask, skeleton, &data.hierarchy);
} else {
    for (bone, index) in &base.paths {
        let weight = mask.bone_weight(bone);
        if weight <= 1e-5 { continue; }
        if let Some(target) = target.get_bone(*bone) {
            base.bones[*index] = if weight >= 1.0 - 1e-5 { target.clone() }
                else { base.bones[*index].scalar_mult(1.0 - weight).linear_add(&target.scalar_mult(weight)).normalize_quat() };
        }
    }
}
base.root_motion = root_motion;
